(function() {
    'use strict';

    var SCORE = {
        1: { d1: { a: 10, b: 4, c: 0 }, d2: { a: 5, b: 2, c: 0 }, d3: { a: 2, b: 0, c: 0 }, d4: { a: 2, b: 1, c: 0 }, d5: { a: 1, b: 0, c: 0 } },
        2: { d1: { a: 8, b: 4, c: 2 }, d2: { a: 5, b: 0, c: 0 }, d3: { a: 8, b: 4, c: 0 }, d4: { a: 3, b: 1, c: 0 }, d5: { a: 6, b: 2, c: 0 } },
        3: { d1: { a: 12, b: 0, c: 0 }, d2: { a: 6, b: 2, c: 0 }, d3: { a: 12, b: 4, c: 0 }, d4: { a: 12, b: 4, c: 0 }, d5: { a: 8, b: 0, c: 0 } }
    };

    var TIMES = ['09:14', '09:42', '10:38'];

    class ServiceLiveAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Service Excellence Live';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    queueLength: 3,
                    csat: 4.30,
                    band: '—',
                    scoreHistory: [],
                    queueHistory: [],
                    csatHistory: [],
                    feedbackText: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { d1: 'a', d2: 'a', d3: 'a', d4: 'a', d5: 'a' };
            }
            var self = this;
            setTimeout(function () { self._updateRoundUI(state); }, 50);
        }

        validateDecisions(decisions) {
            var ids = ['d1', 'd2', 'd3', 'd4', 'd5'];
            for (var i = 0; i < ids.length; i++) {
                var sel = document.getElementById(ids[i] + 'Input');
                if (sel) decisions[ids[i]] = sel.value;
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var d = state.decisions;
            var sc = SCORE[period] || {};
            var roundScore = 0;
            ['d1', 'd2', 'd3', 'd4', 'd5'].forEach(function (id) {
                var pts = (sc[id] && sc[id][d[id]] !== undefined) ? sc[id][d[id]] : 0;
                roundScore += pts;
            });

            var csatDelta = 0;
            var queueDelta = 0;
            if (period === 1) {
                if (d.d1 === 'a') { csatDelta += 0.10; queueDelta -= 1; }
                else if (d.d1 === 'b') { csatDelta -= 0.05; queueDelta += 4; }
                else { csatDelta -= 0.20; queueDelta += 8; }
                if (d.d2 === 'a') queueDelta -= 1;
                if (d.d3 === 'a') csatDelta += 0.05;
                if (d.d3 === 'b') csatDelta -= 0.05;
                if (d.d5 === 'b') { queueDelta += 6; csatDelta -= 0.10; }
            } else if (period === 2) {
                queueDelta += 14;
                if (d.d1 === 'a' && d.d2 === 'a') { csatDelta += 0.15; queueDelta -= 5; }
                if (d.d3 === 'c') { csatDelta -= 0.20; queueDelta += 5; }
                if (d.d3 === 'a') csatDelta += 0.10;
                if (d.d4 === 'c') csatDelta -= 0.15;
                if (d.d4 === 'b') csatDelta -= 0.05;
                if (d.d5 === 'a') csatDelta += 0.05;
            } else if (period === 3) {
                queueDelta -= 8;
                if (d.d1 === 'a') csatDelta += 0.10;
                if (d.d1 === 'c') csatDelta -= 0.15;
                if (d.d3 === 'a') csatDelta += 0.05;
                if (d.d4 === 'a') csatDelta += 0.05;
                if (d.d2 === 'c') csatDelta -= 0.10;
            }

            state.domainState.totalScore += roundScore;
            state.domainState.queueLength = Math.max(0, state.domainState.queueLength + queueDelta);
            state.domainState.csat = Math.max(1, Math.min(5, state.domainState.csat + csatDelta));
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.queueHistory.push(state.domainState.queueLength);
            state.domainState.csatHistory.push(parseFloat(state.domainState.csat.toFixed(2)));

            var maxSoFar = (period === 1) ? 20 : (period === 2) ? 50 : 100;
            var pct = (state.domainState.totalScore / maxSoFar) * 100;
            var band;
            if (pct >= 90) band = window.mySimulation.t('band_distinction');
            else if (pct >= 75) band = window.mySimulation.t('band_credit');
            else if (pct >= 60) band = window.mySimulation.t('band_pass');
            else band = window.mySimulation.t('band_refer');
            state.domainState.band = band;

            // FIX v1.1.0 - expose a score the Express reporting layer reads.
            // results_utils.php::express_resolveDomainScore looks for
            // domainState.performance.overallScore first, then top-level `score`.
            // The original wrote neither (only totalScore), so the instructor panel
            // rendered an empty "-". totalScore is 0-100 by design (max 100 at R3).
            state.domainState.score = state.domainState.totalScore;
            state.domainState.performance = { overallScore: state.domainState.totalScore, grade: this._grade(pct) };

            var feedback = this._buildFeedback(period, d, roundScore);
            state.domainState.feedbackText = feedback;

            var self = this;
            setTimeout(function () {
                self._updateRoundUI({ currentPeriod: state.currentPeriod + 1 });
                self._showFeedback(feedback);
            }, 300);

            return {
                period: period,
                roundScore: roundScore,
                cumulativeScore: state.domainState.totalScore,
                queue: state.domainState.queueLength,
                csat: parseFloat(state.domainState.csat.toFixed(2)),
                band: band
            };
        }

        _buildFeedback(period, d, roundScore) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var lines = [];
            lines.push('<strong>' + t('feedback_round_score') + ': ' + roundScore + '</strong>');
            if (period === 1) {
                if (d.d1 === 'a') lines.push('✓ ' + t('fb_r1_d1_a'));
                else if (d.d1 === 'b') lines.push('⚠ ' + t('fb_r1_d1_b'));
                else lines.push('✗ ' + t('fb_r1_d1_c'));

                if (d.d2 === 'a') lines.push('✓ ' + t('fb_r1_d2_a'));
                else if (d.d2 === 'b') lines.push('⚠ ' + t('fb_r1_d2_b'));
                else lines.push('✗ ' + t('fb_r1_d2_c'));

                if (d.d3 === 'a') lines.push('✓ ' + t('fb_r1_d3_a'));
                else if (d.d3 === 'b') lines.push('✗ ' + t('fb_r1_d3_b'));
                else lines.push('⚠ ' + t('fb_r1_d3_c'));

                if (d.d5 === 'b') lines.push('✗ ' + t('fb_r1_d5_b'));
                else lines.push('✓ ' + t('fb_r1_d5_a'));
            } else if (period === 2) {
                if (d.d1 === 'a') lines.push('✓ ' + t('fb_r2_d1_a'));
                else lines.push('⚠ ' + t('fb_r2_d1_other'));

                if (d.d2 === 'a') lines.push('✓ ' + t('fb_r2_d2_a'));
                else lines.push('⚠ ' + t('fb_r2_d2_other'));

                if (d.d3 === 'a') lines.push('✓ ' + t('fb_r2_d3_a'));
                else if (d.d3 === 'b') lines.push('⚠ ' + t('fb_r2_d3_b'));
                else lines.push('✗ ' + t('fb_r2_d3_c'));

                if (d.d4 === 'a') lines.push('✓ ' + t('fb_r2_d4_a'));
                else if (d.d4 === 'b') lines.push('⚠ ' + t('fb_r2_d4_b'));
                else lines.push('✗ ' + t('fb_r2_d4_c'));

                if (d.d5 === 'a') lines.push('✓ ' + t('fb_r2_d5_a'));
                else lines.push('⚠ ' + t('fb_r2_d5_other'));
            } else if (period === 3) {
                if (d.d1 === 'a') lines.push('✓ ' + t('fb_r3_d1_a'));
                else lines.push('✗ ' + t('fb_r3_d1_other'));

                if (d.d2 === 'a') lines.push('✓ ' + t('fb_r3_d2_a'));
                else lines.push('⚠ ' + t('fb_r3_d2_other'));

                if (d.d3 === 'a') lines.push('✓ ' + t('fb_r3_d3_a'));
                else if (d.d3 === 'b') lines.push('⚠ ' + t('fb_r3_d3_b'));
                else lines.push('✗ ' + t('fb_r3_d3_c'));

                if (d.d4 === 'a') lines.push('✓ ' + t('fb_r3_d4_a'));
                else lines.push('⚠ ' + t('fb_r3_d4_other'));

                if (d.d5 === 'a') lines.push('✓ ' + t('fb_r3_d5_a'));
                else lines.push('✗ ' + t('fb_r3_d5_other'));
            }
            return lines.join('<br>');
        }

        _showFeedback(text) {
            var panel = document.getElementById('feedbackPanel');
            var fbText = document.getElementById('feedbackText');
            if (panel && fbText) {
                fbText.innerHTML = text;
                panel.style.display = 'block';
            }
        }

        _updateRoundUI(state) {
            var period = state.currentPeriod || 1;
            if (period > 3) period = 3;
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };

            var clockEl = document.getElementById('incidentClock');
            if (clockEl) clockEl.textContent = TIMES[period - 1];

            var roundNameEl = document.getElementById('roundName');
            if (roundNameEl) roundNameEl.textContent = '— ' + t('r' + period + '_name');

            var briefingTitleEl = document.getElementById('briefingTitle');
            var briefingTextEl = document.getElementById('briefingText');
            if (briefingTitleEl) briefingTitleEl.textContent = t('r' + period + '_brief_title');
            if (briefingTextEl) briefingTextEl.innerHTML = t('r' + period + '_brief');

            for (var i = 1; i <= 5; i++) {
                var labelEl = document.getElementById('d' + i + 'Label');
                var selectEl = document.getElementById('d' + i + 'Input');
                if (labelEl) labelEl.textContent = t('r' + period + '_d' + i + '_label');
                if (selectEl) {
                    selectEl.innerHTML = '';
                    var optKeys = ['a', 'b', 'c'];
                    for (var j = 0; j < optKeys.length; j++) {
                        var k = optKeys[j];
                        var optKey = 'r' + period + '_d' + i + '_' + k;
                        var optText = t(optKey);
                        if (optText === optKey) continue;
                        var opt = document.createElement('option');
                        opt.value = k;
                        opt.textContent = optText;
                        selectEl.appendChild(opt);
                    }
                    selectEl.value = 'a';
                }
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('queueDisplay', 'domainState.queueLength', function (v) { return Math.round(v) + ''; });
            uiManager.bind('csatDisplay', 'domainState.csat', function (v) { return Number(v).toFixed(2); });
            uiManager.bind('bandDisplay', 'domainState.band');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore', function (v) { return Math.round(v).toString(); });
            uiManager.bind('roundScoreDisplay', 'results.roundScore', function (v) { return (v !== undefined && v !== null) ? v.toString() : '0'; });
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            backgroundColor: 'rgba(6, 182, 212, 0.7)',
                            borderColor: '#06b6d4',
                            borderWidth: 2,
                            borderRadius: 4
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: false },
