        getPerformanceSummary(history) {
            var t = this._t();
            var periods = history ? history.length : 0;
            if (!periods) return { totalPeriods: 0 };
            var totalScore = history.reduce(function (s, r) { return s + ((r.results && r.results.roundScore) || 0); }, 0);
            var avgScore = totalScore / periods;
            var verdictKey = 'perf_refer', insightKey = 'summary_refer';
            if (totalScore >= 90) { verdictKey = 'perf_distinction'; insightKey = 'summary_distinction'; }
